+function buildToolChoiceReplacement(sourceFormat) {
+  const name = NINEROUTER_WEB_SEARCH_FALLBACK_TOOL_NAME;
+  if (sourceFormat === FORMATS.CLAUDE) {
+    return { type: "tool", name };
+  }
