+  const builtInSearchTools = tools.filter(isBuiltInWebSearchTool);
+  if (builtInSearchTools.length === 0) return { body, fallback: disabled };
+
+  if (supportsNativeWebSearchFallbackBypass(options)) return { body, fallback: disabled };
